#!/usr/bin/env python3
"""Water--power case study, part 2: restoration, storage, and annual risk.

Builds on run_water_power_case.py (facility attachments) and adds time and
probability to the single-outage screen.

Electricity (generated MV network, unchanged in normal operation)
    * Switch points at every MV node (ring-main units at the stations,
      switchable branch points); a fault trips the feeder breaker.
    * Open-ring layer generated by rule: every leaf station receives one
      normally-open tie cable to the nearest station that closes a real loop
      (tree path >= K_LOOP x straight distance, straight distance <= D_TIE_KM);
      length = network detour factor x straight distance; cable type = the
      dominant MV cable of the accepted model.
    * Per MV-line fault: the faulted segment is isolated; the rest of the
      feeder is re-energized after the switching time; downstream stations are
      restored through ties if an AC power flow of the MV equivalent stays
      within 100 % loading and the MV voltage floor (greedy, largest feasible
      connected block first); all others wait for repair.
    * Fault rate: VDE FNN 2023 short-circuit fault rate of the German MV level;
      switching and repair times exponential with the RBTS means.

Water
    * Each pressure zone stores s hours of its average-day demand; the
      pressure-dependent EPANET states of the average day give the population
      equivalent (PE) without water and the unserved flow once storage is spent.
    * Annual risk: expected unserved water E[U] (m3/a) and PE-hours (PE h/a),
      in closed form for exponential switching and repair times.
    * Prolonged outage (Klise et al. 2022 approach): extended-period EPANET
      simulation of a city-wide blackout with tanks, per backup variant.

Usage: python run_water_reliability.py --repo /path/to/Urban4 --case results/water_power_case --out results/water_power_case
"""
from __future__ import annotations

import argparse
import itertools
import json
import math
import tempfile
import warnings
from pathlib import Path

import networkx as nx
import numpy as np
import pandas as pd
import pandapower as pp
import wntr

warnings.filterwarnings("ignore")

FAULT_RATE_PER_KM = 2.31 / 100.0   # VDE FNN 2023, MV short-circuit faults per km and year
T_SW_H = 1.0                       # mean switching time (RBTS)
T_REP_H = 5.0                      # mean repair time (RBTS); sensitivity below
T_REP_SENS_H = 24.0
D_TIE_KM, K_LOOP = 1.0, 3.0        # tie rule
LOADING_MAX = 100.0
LV_FLOOR_PU = 0.90                 # customer voltage floor; MV floor = this + largest base LV drop
P_MIN_M, P_REQ_M, P_EXP = 0.0, 27.5, 0.5
STORAGE_H = [0, 0.5, 1, 2, 3, 4, 6, 8, 12, 16, 24, 36, 48]
TANK_DEPTH_M = 5.0
BLACKOUT_H = 72
EPS_STEP_S = 900


# ================================================================ electricity
def geo_of(net):
    return net.bus.geo.map(lambda g: json.loads(g)["coordinates"] if isinstance(g, str) else g["coordinates"])


def km(a, b):
    return math.hypot((a[0] - b[0]) * 111.32 * math.cos(math.radians(0.5 * (a[1] + b[1]))), (a[1] - b[1]) * 111.2)


def mv_equivalent(net, facility_loads):
    """MV network with each MV/LV station represented by its HV-side power."""
    pp.runpp(net, numba=False)
    mvb = net.bus.index[net.bus.vn_kv >= 1.0]
    m = pp.create_empty_network(sn_mva=net.sn_mva)
    for b in mvb:
        pp.create_bus(m, vn_kv=float(net.bus.vn_kv.at[b]), name=net.bus.name.at[b], index=int(b))
    mvl = net.line[net.line.from_bus.isin(mvb)]
    for i, r in mvl.iterrows():
        pp.create_line_from_parameters(m, int(r.from_bus), int(r.to_bus), float(r.length_km), float(r.r_ohm_per_km),
                                       float(r.x_ohm_per_km), float(r.c_nf_per_km), float(r.max_i_ka),
                                       parallel=int(r.parallel), name=str(r["name"]), index=int(i))
    eg = net.ext_grid.iloc[0]
    pp.create_ext_grid(m, int(eg.bus), vm_pu=float(eg.vm_pu), va_degree=float(eg.va_degree))
    for t, r in net.trafo.iterrows():
        pp.create_load(m, int(r.hv_bus), p_mw=float(net.res_trafo.p_hv_mw.at[t]),
                       q_mvar=float(net.res_trafo.q_hv_mvar.at[t]), name=str(r["name"]))
    for bus, p_mw in facility_loads:
        pp.create_load(m, int(bus), p_mw=p_mw, q_mvar=p_mw * math.tan(math.acos(0.9)), name="facility")
    # largest LV voltage drop below its station in the accepted base state
    lv_drop = 0.0
    g = nx.Graph()
    g.add_edges_from(zip(net.line.from_bus, net.line.to_bus))
    for t, r in net.trafo.iterrows():
        comp = nx.node_connected_component(g, int(r.lv_bus))
        vmin = float(net.res_bus.vm_pu.loc[list(comp)].min())
        lv_drop = max(lv_drop, float(net.res_bus.vm_pu.at[int(r.hv_bus)]) - vmin)
    return m, lv_drop


class Restorer:
    def __init__(self, m, tree_edges, ties, v_floor):
        self.m = m
        self.v_floor = v_floor
        self.tree_line = {}  # frozenset(u,v) -> line index
        for i, r in m.line.iterrows():
            self.tree_line[frozenset((int(r.from_bus), int(r.to_bus)))] = int(i)
        self.tie_idx = []
        typ = m.line.loc[m.line.max_i_ka.eq(m.line.max_i_ka.mode().iloc[0])].iloc[0]
        for k, t in enumerate(ties):
            idx = pp.create_line_from_parameters(m, t["a"], t["b"], t["length_km"], float(typ.r_ohm_per_km),
                                                 float(typ.x_ohm_per_km), float(typ.c_nf_per_km), float(typ.max_i_ka),
                                                 name=f"TIE{k:03d}", in_service=False, index=900000 + k)
            self.tie_idx.append(int(idx))
        self.n_tree = len(self.tree_line)
        self.calls = 0

    def check(self, energized: set, ties_closed: list, faulted: int) -> bool:
        m = self.m
        ins = np.zeros(len(m.line), bool)
        fb, tb = m.line.from_bus.to_numpy(), m.line.to_bus.to_numpy()
        is_tree = m.line.index.to_numpy() < 900000
        e = np.fromiter((b in energized for b in fb), bool, len(fb)) & np.fromiter((b in energized for b in tb), bool, len(tb))
        ins[is_tree & e] = True
        ins[m.line.index.to_numpy() == faulted] = False
        ins[m.line.index.isin(ties_closed)] = True
        m.line["in_service"] = ins
        self.calls += 1
        try:
            pp.runpp(m, numba=False, max_iteration=30, init="auto")
        except Exception:
            return False
        if not m.converged:
            return False
        ln = m.res_line.loading_percent[ins]
        vm = m.res_bus.vm_pu.dropna()
        return bool(ln.max() <= LOADING_MAX + 1e-6 and vm.min() >= self.v_floor - 1e-9)


def build_ties(tree, root, stations, geo, detour):
    """Normally-open ties from every leaf station (open-ring layer)."""
    und = tree.to_undirected()
    leaves = [s for s in stations if und.degree(s) == 1 and s != root]
    dist_tree = {}
    ties, seen = [], set()
    st_xy = {s: geo.at[s] for s in stations}
    for v in leaves:
        lens = nx.single_source_dijkstra_path_length(und, v, weight="km")
        best = None
        for u in stations:
            if u == v:
                continue
            d = km(st_xy[v], st_xy[u])
            if d > D_TIE_KM or d < 1e-3:
                continue
            if lens[u] < K_LOOP * d:
                continue
            if best is None or d < best[1]:
                best = (u, d)
        if best is None:
            continue
        key = frozenset((v, best[0]))
        if key in seen:
            continue
        seen.add(key)
        ties.append({"a": int(v), "b": int(best[0]), "straight_km": best[1], "length_km": detour * best[1],
                     "loop_km": float(lens[best[0]])})
    return ties, leaves


def restore(rest: Restorer, tree, D: set, E: set, ties, faulted: int):
    """Greedy restoration of the de-energized set D through normally-open ties."""
    U, R, closed = set(D), set(E), []
    und = tree.to_undirected()
    progress = True
    order_ties = sorted(range(len(ties)), key=lambda k: ties[k]["length_km"])
    while progress and U:
        progress = False
        for k in order_ties:
            a, b = ties[k]["a"], ties[k]["b"]
            if a in U and b in R:
                pass
            elif b in U and a in R:
                a, b = b, a
            else:
                continue
            comp = nx.node_connected_component(und.subgraph(U), a)
            order = list(nx.bfs_tree(und.subgraph(comp), a))
            tie_line = rest.tie_idx[k]
            if rest.check(R | set(order), closed + [tie_line], faulted):
                blk = order
            else:
                best = 0
                lo_k, hi_k = 1, len(order) - 1
                while lo_k <= hi_k:
                    mid = (lo_k + hi_k) // 2
                    if rest.check(R | set(order[:mid]), closed + [tie_line], faulted):
                        best, lo_k = mid, mid + 1
                    else:
                        hi_k = mid - 1
                blk = order[:best]
            if blk:
                R |= set(blk)
                U -= set(blk)
                closed.append(tie_line)
                progress = True
    return set(D) - U, closed


# ================================================================ water
class WaterStates:
    """Average-day EPANET states for sets of zones without their own supply."""

    def __init__(self, inp, nodes, ledger, heads):
        self.inp, self.heads = inp, heads
        svc = nodes[nodes.node_type.eq("building_service")][["node_id", "building_id", "pressure_zone_id"]]
        self.svc = svc.merge(ledger[["building_id", "population"]], on="building_id", how="left").fillna({"population": 0.0})
        wn = wntr.network.WaterNetworkModel(str(inp))
        self.q = pd.Series({i: wn.get_node(i).demand_timeseries_list[0].base_value for i in self.svc.node_id})
        self.pop = self.svc.set_index("node_id").population.reindex(self.q.index).fillna(0.0)
        self.zone = self.svc.set_index("node_id").pressure_zone_id.reindex(self.q.index)
        self.cache = {}

    def model(self):
        wn = wntr.network.WaterNetworkModel(str(self.inp))
        wn.options.hydraulic.demand_model = "PDD"
        wn.options.hydraulic.minimum_pressure = P_MIN_M
        wn.options.hydraulic.required_pressure = P_REQ_M
        wn.options.hydraulic.pressure_exponent = P_EXP
        return wn

    def state(self, out: frozenset):
        """PE without water and unserved m3/h when the zones in `out` lost their own supply."""
        if out in self.cache:
            return self.cache[out]
        if "WZ1" in out:
            r = {"pe": float(self.pop.sum()), "u_m3h": float(self.q.sum() * 3600.0)}
        elif not out:
            r = {"pe": 0.0, "u_m3h": 0.0}
        else:
            wn = self.model()
            wn.options.time.duration = 0
            for z in out:   # booster zone on bypass at the waterworks-zone head
                wn.get_node(f"{z}_BOUNDARY").base_head = min(self.heads["WZ1"], self.heads[z])
            res = wntr.sim.EpanetSimulator(wn).run_sim(file_prefix=str(Path(tempfile.mkdtemp()) / "w"))
            dlv = res.node["demand"].iloc[0].reindex(self.q.index).fillna(0.0).clip(lower=0.0)
            frac = (dlv / self.q.replace(0, np.nan)).fillna(1.0).clip(0.0, 1.0)
            r = {"pe": float((self.pop * (1 - frac)).sum()), "u_m3h": float((self.q - dlv).clip(lower=0).sum() * 3600.0)}
        self.cache[out] = r
        return r


def e_excess(s, a, b=None):
    """E[(D - s)+] for D ~ Exp(a) (b None) or D = Exp(a) + Exp(b)."""
    if b is None:
        return a * math.exp(-s / a)
    if abs(a - b) < 1e-9:
        b = b + 1e-6
    return (b * b * math.exp(-s / b) - a * a * math.exp(-s / a)) / (b - a)


def p_exceed(s, a, b=None):
    if b is None:
        return math.exp(-s / a)
    if abs(a - b) < 1e-9:
        b = b + 1e-6
    return (b * math.exp(-s / b) - a * math.exp(-s / a)) / (b - a)


def blackout_eps(ws: WaterStates, storage_h: float, backup: set, zb: pd.DataFrame):
    """Extended-period PDD simulation of a city-wide blackout with zone tanks."""
    wn = ws.model()
    wn.options.time.duration = BLACKOUT_H * 3600
    wn.options.time.hydraulic_timestep = EPS_STEP_S
    wn.options.time.report_timestep = EPS_STEP_S
    zq = ws.q.groupby(ws.zone).sum()
    tanks = {}
    for z in ["WZ1", "WZ2", "WZ3", "WZ4"]:
        res = wn.get_node(f"{z}_BOUNDARY")
        link = wn.get_link(f"{z}_CONTROLLED_BOUNDARY")
        root = link.end_node_name if link.start_node_name == f"{z}_BOUNDARY" else link.start_node_name
        powered = z in backup and (z == "WZ1" or "WZ1" in backup)
        if powered:          # station keeps pumping: storage is not drawn down
            continue
        vol = storage_h * 3600.0 * float(zq[z])
        diam = math.sqrt(4.0 * max(vol, 1.0) / (math.pi * TANK_DEPTH_M))
        wn.add_tank(f"{z}_TANK", elevation=float(res.base_head) - TANK_DEPTH_M, init_level=TANK_DEPTH_M,
                    min_level=0.0, max_level=TANK_DEPTH_M, diameter=diam, coordinates=res.coordinates)
        wn.add_pipe(f"{z}_TANK_LINK", f"{z}_TANK", root, length=1.0, diameter=0.6, roughness=130)
        tanks[z] = root
        link.initial_status = wntr.network.LinkStatus.Closed
        if z != "WZ1" and z not in backup and "WZ1" in backup:
            # booster off, waterworks on: bypass from the waterworks zone at its head (check valve)
            wn.add_reservoir(f"{z}_BYPASS", base_head=min(ws.heads["WZ1"], ws.heads[z]), coordinates=res.coordinates)
            wn.add_pipe(f"{z}_BYPASS_LINK", f"{z}_BYPASS", root, length=1.0, diameter=0.6, roughness=130,
                        check_valve=True)
            # EPANET keeps an empty tank at its bottom head; close its outlet so the bypass takes over
            cond = wntr.network.controls.ValueCondition(wn.get_node(f"{z}_TANK"), "level", "<", 0.02)
            act = wntr.network.controls.ControlAction(wn.get_link(f"{z}_TANK_LINK"), "status",
                                                      wntr.network.LinkStatus.Closed)
            wn.add_control(f"{z}_TANK_EMPTY", wntr.network.controls.Control(cond, act))
    res = wntr.sim.EpanetSimulator(wn).run_sim(file_prefix=str(Path(tempfile.mkdtemp()) / "b"))
    t_h = res.node["demand"].index.to_numpy() / 3600.0
    dlv = res.node["demand"][ws.q.index].clip(lower=0.0)
    level = res.node["pressure"][[f"{z}_TANK" for z in tanks]] if tanks else pd.DataFrame(index=res.node["demand"].index)
    # EPANET closes an empty tank but reports demand at nodes it can no longer feed;
    # zones without a live source after their tank empties are set to zero delivery.
    for z in tanks:
        has_source = (z in backup and (z == "WZ1" or "WZ1" in backup)) or (z != "WZ1" and "WZ1" in backup)
        if has_source:
            continue
        empty = level[f"{z}_TANK"].to_numpy() <= 0.01
        if empty.any():
            ids = ws.q.index[ws.zone.eq(z)]
            dlv.loc[empty, ids] = 0.0
    frac = (dlv / ws.q.replace(0, np.nan)).fillna(1.0).clip(0.0, 1.0)
    pe = (frac.rsub(1.0) * ws.pop).sum(axis=1)
    zones = ["WZ1", "WZ2", "WZ3", "WZ4"]
    zone_pe = {z: (frac.loc[:, ws.zone.eq(z).to_numpy()].rsub(1.0) * ws.pop[ws.zone.eq(z)]).sum(axis=1) for z in zones}
    out = pd.DataFrame({"t_h": t_h, "pe_without_water": pe.to_numpy(),
                        **{f"pe_{z}": zone_pe[z].to_numpy() for z in zones},
                        **{f"level_{z}": (level[f"{z}_TANK"].to_numpy() if z in tanks else np.full(len(t_h), np.nan))
                           for z in zones}})
    return out


# ================================================================ main
def main() -> None:
    ap = argparse.ArgumentParser()
    ap.add_argument("--repo", type=Path, required=True)
    ap.add_argument("--case", type=Path, required=True, help="outputs of run_water_power_case.py")
    ap.add_argument("--out", type=Path, required=True)
    a = ap.parse_args()
    ms = a.repo / "outputs" / "municipal_scale_v2.5.0"
    out = a.out
    out.mkdir(parents=True, exist_ok=True)
    summ0 = json.loads((a.case / "water_power_summary.json").read_text())
    fac = pd.read_csv(a.case / "facility_attachments.csv")

    net = pp.from_json(str(ms / "electricity_municipal_pandapower.json"))
    geo = geo_of(net)
    name_to_bus = pd.Series(net.bus.index, index=net.bus.name)
    fac["bus"] = fac.bus_name.map(name_to_bus).astype(int)

    # ---- trees
    g_all = nx.Graph()
    g_all.add_edges_from(zip(net.line.from_bus, net.line.to_bus))
    g_all.add_edges_from(zip(net.trafo.hv_bus, net.trafo.lv_bus))
    root = int(net.ext_grid.bus.iloc[0])
    tree_all = nx.bfs_tree(g_all, root)
    mvb = set(int(b) for b in net.bus.index[net.bus.vn_kv >= 1.0])
    mvl = net.line[net.line.from_bus.isin(mvb)]
    g_mv = nx.Graph()
    for i, r in mvl.iterrows():
        g_mv.add_edge(int(r.from_bus), int(r.to_bus), km=float(r.length_km), line=int(i))
    tree = nx.bfs_tree(g_mv, root)
    for u, v in tree.edges:
        tree[u][v]["km"] = g_mv[u][v]["km"]
    depth = nx.single_source_shortest_path_length(tree, root)
    feeder = {}
    for c in tree.successors(root):
        for n in nx.descendants(tree, c) | {c}:
            feeder[n] = c
    stations = sorted(int(b) for b in net.trafo.hv_bus)

    # station of every LV bus, customers per station
    st_of = {}
    for t, r in net.trafo.iterrows():
        for n in nx.descendants(tree_all, int(r.lv_bus)) | {int(r.lv_bus)}:
            st_of[n] = int(r.hv_bus)
    cust = net.load.bus.map(st_of).value_counts().reindex(stations).fillna(0).astype(int)
    n_cust = int(cust.sum())
    fac["station_mv_bus"] = [b if b in mvb else st_of[b] for b in fac.bus]

    # ---- MV equivalent with facility loads, open-ring layer
    bk = summ0["backup_power_kw"]
    wl = fac[fac.kind.eq("water")].set_index("facility")
    facility_loads = [(wl.at["WZ1", "station_mv_bus"], bk["waterworks_duty"] / 1e3)] + \
                     [(wl.at[z, "station_mv_bus"], bk[z] / 1e3) for z in ["WZ2", "WZ3", "WZ4"]]
    m, lv_drop = mv_equivalent(net, facility_loads)
    v_floor = LV_FLOOR_PU + lv_drop
    pp.runpp(m, numba=False)
    base_loading = net.res_line.loading_percent
    check = (m.res_line.loading_percent - base_loading.reindex(m.line.index)).abs().max()
    print(f"MV equivalent: max loading difference to full model {check:.2f} pp; MV voltage floor {v_floor:.3f} pu", flush=True)

    route = mvl.length_km.to_numpy()
    straight = np.array([km(geo.at[int(r.from_bus)], geo.at[int(r.to_bus)]) for r in mvl.itertuples()])
    ok = straight > 0.02
    detour = float(route[ok].sum() / straight[ok].sum())
    ties, leaves = build_ties(tree, root, stations, geo, detour)
    rest = Restorer(m, tree.edges, ties, v_floor)
    tie_df = pd.DataFrame(ties)
    tie_df["a_name"] = net.bus.name.loc[tie_df.a].to_numpy()
    tie_df["b_name"] = net.bus.name.loc[tie_df.b].to_numpy()
    tie_df["cross_feeder"] = [feeder[x] != feeder[y] for x, y in zip(tie_df.a, tie_df.b)]
    tie_df["geometry_json"] = [json.dumps({"type": "LineString", "coordinates": [list(geo.at[x]), list(geo.at[y])]})
                               for x, y in zip(tie_df.a, tie_df.b)]
    tie_df.to_csv(out / "open_ring_ties.csv", index=False)
    print(f"ties: {len(ties)} from {len(leaves)} leaf stations, {tie_df.length_km.sum():.1f} km, "
          f"{int(tie_df.cross_feeder.sum())} cross-feeder, detour {detour:.3f}", flush=True)

    # ---- fault enumeration
    rows = []
    wz = ["WZ1", "WZ2", "WZ3", "WZ4"]
    wbus = {z: int(wl.at[z, "station_mv_bus"]) for z in wz}
    lift = fac[fac.kind.eq("wastewater")].set_index("facility")
    ls_all = pd.read_csv(ms / "wastewater_pump_stations_municipal.csv").set_index("map_id")
    inflow_m3h = (ls_all.annual_sanitary_m3 / (365.0 * 24.0)).to_dict()
    for idx, r in mvl.iterrows():
        u, v = int(r.from_bus), int(r.to_bus)
        child = v if depth[v] > depth[u] else u
        n_c = int(r.parallel)
        lam = FAULT_RATE_PER_KM * float(r.length_km) * n_c
        rec = {"line": str(r["name"]), "length_km": float(r.length_km), "circuits": n_c, "lambda_per_a": lam,
               "base_loading_pct": float(base_loading.at[idx])}
        if n_c >= 2 and base_loading.at[idx] * n_c / (n_c - 1) <= LOADING_MAX:
            rec.update({"interrupting": False})
            for cfg in ["R0", "R1"]:
                rec[f"{cfg}_sw_stations"] = ""
                rec[f"{cfg}_rep_stations"] = ""
            rows.append(rec)
            continue
        D = nx.descendants(tree, child) | {child}
        fdr = feeder[child]
        same = {n for n in tree.nodes if feeder.get(n) == fdr} - D
        E = set(tree.nodes) - D
        restored, closed = restore(rest, tree, D, E, ties, int(idx))
        st_D = [s for s in stations if s in D]
        st_same = [s for s in stations if s in same]
        rec.update({"interrupting": True, "D_stations": len(st_D),
                    "R0_sw_stations": " ".join(map(str, st_same)), "R0_rep_stations": " ".join(map(str, st_D)),
                    "R1_sw_stations": " ".join(map(str, st_same + [s for s in st_D if s in restored])),
                    "R1_rep_stations": " ".join(map(str, [s for s in st_D if s not in restored])),
                    "R1_ties_closed": len(closed), "R1_restored_stations": sum(s in restored for s in st_D)})
        rows.append(rec)
        if len(rows) % 50 == 0:
            print(f"  {len(rows)} faults, {rest.calls} power flows", flush=True)
    flt = pd.DataFrame(rows)

    def cls(rec, cfg, bus):
        if not rec.get("interrupting", False):
            return 0
        if str(bus) in str(rec[f"{cfg}_rep_stations"]).split():
            return 2
        if str(bus) in str(rec[f"{cfg}_sw_stations"]).split():
            return 1
        return 0

    for cfg in ["R0", "R1"]:
        for z in wz:
            flt[f"{cfg}_{z}"] = [cls(rec, cfg, wbus[z]) for rec in rows]
        for f_id, rr in lift.iterrows():
            flt[f"{cfg}_LS_{f_id}"] = [cls(rec, cfg, int(rr.station_mv_bus)) for rec in rows]
        n_sw = np.array([sum(cust.get(int(s), 0) for s in str(rec.get(f"{cfg}_sw_stations", "")).split()) for rec in rows])
        n_rep = np.array([sum(cust.get(int(s), 0) for s in str(rec.get(f"{cfg}_rep_stations", "")).split()) for rec in rows])
        flt[f"{cfg}_cust_sw"], flt[f"{cfg}_cust_rep"] = n_sw, n_rep
    flt.to_csv(out / "mv_fault_restoration.csv", index=False)

    # ---- electricity reliability indices
    rel = {}
    for cfg in ["R0", "R1"]:
        for trep in [T_REP_H, T_REP_SENS_H]:
            saifi = float((flt.lambda_per_a * (flt[f"{cfg}_cust_sw"] + flt[f"{cfg}_cust_rep"])).sum() / n_cust)
            saidi = float((flt.lambda_per_a * (flt[f"{cfg}_cust_sw"] * T_SW_H +
                                               flt[f"{cfg}_cust_rep"] * (T_SW_H + trep))).sum() / n_cust * 60.0)
            rel[f"{cfg}_rep{trep:g}h"] = {"saifi_per_a": saifi, "saidi_min_per_a": saidi,
                                          "cust_h_repair_share": float((flt.lambda_per_a * flt[f"{cfg}_cust_rep"] * trep).sum() /
                                                                      max((flt.lambda_per_a * (flt[f"{cfg}_cust_sw"] * T_SW_H + flt[f"{cfg}_cust_rep"] * (T_SW_H + trep))).sum(), 1e-12))}
    interrupting = flt[flt.interrupting.astype(bool)]
    restored_share = float((interrupting.R1_restored_stations.fillna(0).sum()) / max(interrupting.D_stations.fillna(0).sum(), 1))

    # ---- water risk
    ledger = pd.read_csv(a.repo / "outputs" / "building_sector_demands.csv")
    wnodes = pd.read_csv(ms / "drinking_water_nodes.csv")
    zb = pd.read_csv(ms / "drinking_water_zone_boundaries.csv")
    heads = dict(zip(zb.pressure_zone_id, zb.selected_boundary_head_m))
    ws = WaterStates(ms / "drinking_water_municipal_average.inp", wnodes, ledger, heads)
    for k in range(0, 4):
        for sub in itertools.combinations(["WZ2", "WZ3", "WZ4"], k):
            ws.state(frozenset(sub))
    ws.state(frozenset({"WZ1"}))

    def sets(row, cfg, backup):
        c = {z: (0 if z in backup else int(row[f"{cfg}_{z}"])) for z in wz}
        eff = {z: (c[z] if z == "WZ1" else max(c[z], c["WZ1"])) for z in wz}   # boosters need the waterworks
        s_all = frozenset(z for z in wz if eff[z] >= 1)
        s_rep = frozenset(z for z in wz if eff[z] >= 2)
        return s_all, s_rep

    backups = {"M0": set(), "M1": {"WZ1"}, "M2": set(wz)}
    risk_rows = []
    for cfg in ["R0", "R1"]:
        for bname, bset in backups.items():
            for trep in [T_REP_H, T_REP_SENS_H]:
                for s in STORAGE_H:
                    eu = epe = ev = 0.0
                    for _, row in flt.iterrows():
                        if not row.get("interrupting", False):
                            continue
                        s_all, s_rep = sets(row, cfg, bset)
                        if not s_all:
                            continue
                        st_all, st_rep = ws.state(s_all), ws.state(s_rep)
                        x_sw = e_excess(s, T_SW_H)
                        x_rep = e_excess(s, T_SW_H, trep) if s_rep else 0.0
                        lam = row.lambda_per_a
                        # PE(t) = PE_all for t < D_sw, PE_rep for D_sw <= t < D_sw + D_rep
                        epe += lam * (st_all["pe"] * x_sw + st_rep["pe"] * (x_rep - x_sw if s_rep else 0.0))
                        eu += lam * (st_all["u_m3h"] * x_sw + st_rep["u_m3h"] * (x_rep - x_sw if s_rep else 0.0))
                        if st_all["pe"] >= 1000.0:
                            ev += lam * (p_exceed(s, T_SW_H, trep) if (s_rep and st_rep["pe"] >= 1000.0) else p_exceed(s, T_SW_H))
                    risk_rows.append({"grid": cfg, "backup": bname, "t_rep_h": trep, "storage_h": s,
                                      "E_unserved_m3_per_a": eu, "E_pe_hours_per_a": epe,
                                      "events_ge_1000pe_per_a": ev})
        print(f"risk {cfg} done", flush=True)
    risk = pd.DataFrame(risk_rows)
    risk.to_csv(out / "water_risk_by_storage.csv", index=False)

    # exposure: km of MV cable whose fault leaves a station out until repair
    expo = {}
    for cfg in ["R0", "R1"]:
        for z in wz:
            sel = flt[flt[f"{cfg}_{z}"].eq(2)]
            sel_sw = flt[flt[f"{cfg}_{z}"].eq(1)]
            expo[f"{cfg}_{z}"] = {"repair_km": float(sel.length_km.sum()), "repair_faults_per_a": float(sel.lambda_per_a.sum()),
                                  "switching_faults_per_a": float(sel_sw.lambda_per_a.sum())}
    # sewage: expected unpumped sanitary volume (no storage credited)
    sew = {}
    for cfg in ["R0", "R1"]:
        for trep in [T_REP_H, T_REP_SENS_H]:
            v = 0.0
            hrs = 0.0
            for f_id in lift.index:
                c = flt[f"{cfg}_LS_{f_id}"]
                dur = np.where(c.eq(2), T_SW_H + trep, np.where(c.eq(1), T_SW_H, 0.0))
                v += float((flt.lambda_per_a * dur).sum() * inflow_m3h.get(f_id, 0.0))
                hrs += float((flt.lambda_per_a * dur).sum())
            sew[f"{cfg}_rep{trep:g}h"] = {"unpumped_m3_per_a": v, "lift_station_outage_h_per_a_total": hrs}

    # ---- prolonged blackout (EPS)
    bo = []
    for s in [12.0, 24.0]:
        for bname, bset in backups.items():
            d = blackout_eps(ws, s, bset, zb)
            d.insert(0, "backup", bname)
            d.insert(0, "storage_h", s)
            bo.append(d)
            ttl = d.loc[d.pe_without_water >= 1000.0, "t_h"]
            print(f"blackout s={s:g} h {bname}: first >=1000 PE at {ttl.min() if len(ttl) else None} h, "
                  f"PE at 72 h {d.pe_without_water.iloc[-1]:.0f}", flush=True)
    bo = pd.concat(bo, ignore_index=True)
    bo.to_csv(out / "blackout_eps.csv", index=False)

    def ttl(sub, thr):
        t = sub.loc[sub.pe_without_water >= thr, "t_h"]
        return float(t.min()) if len(t) else None

    summary = {
        "assumptions": {
            "fault_rate_per_100km_a": FAULT_RATE_PER_KM * 100, "fault_rate_source": "VDE FNN Stoerungs- und Verfuegbarkeitsstatistik 2023 (MV)",
            "t_switch_mean_h": T_SW_H, "t_repair_mean_h": T_REP_H, "t_repair_sensitivity_h": T_REP_SENS_H,
            "durations": "exponential", "tie_rule": {"max_straight_km": D_TIE_KM, "min_loop_ratio": K_LOOP, "detour_factor": detour},
            "restoration_limits": {"loading_pct": LOADING_MAX, "mv_voltage_floor_pu": v_floor, "lv_floor_pu": LV_FLOOR_PU,
                                   "largest_base_lv_drop_pu": lv_drop},
            "parallel_circuits": "single-circuit fault is non-interrupting if the remaining circuits stay <= 100 %",
            "storage": "s hours of average-day zone demand per zone; zones isolated while their supply is lost",
            "water_states": "average-day EPANET PDD; booster zones fall back to the waterworks-zone head once storage is spent",
        },
        "mv_km": float(mvl.length_km.sum()), "faults_per_a": float((FAULT_RATE_PER_KM * mvl.length_km * mvl.parallel).sum()),
        "customers": n_cust, "leaf_stations": len(leaves), "ties": len(ties), "tie_km": float(tie_df.length_km.sum()),
        "tie_cost_meur_at_140keur_per_km": float(tie_df.length_km.sum() * 0.14),
        "cross_feeder_ties": int(tie_df.cross_feeder.sum()),
        "non_interrupting_parallel_lines": int((~flt.interrupting.astype(bool)).sum()),
        "restored_station_share_R1": restored_share,
        "power_flows": rest.calls,
        "reliability": rel, "fnn_2023_national": {"saifi_per_a": 0.34, "saidi_min_per_a": 13.7},
        "exposure": expo, "sewage": sew,
        "water_states_avg": {"+".join(sorted(k)) or "none": v for k, v in ws.cache.items()},
        "zone_avg_demand_lps": {z: float(ws.q[ws.zone.eq(z)].sum() * 1000) for z in wz},
        "risk_key": risk[risk.storage_h.isin([0, 2, 6, 24])].to_dict(orient="records"),
        "blackout": {f"s{s:g}_{b}": {"first_1000pe_h": ttl(bo[(bo.storage_h == s) & (bo.backup == b)], 1000.0),
                                      "pe_at_72h": float(bo[(bo.storage_h == s) & (bo.backup == b)].pe_without_water.iloc[-1]),
                                      "pe_max": float(bo[(bo.storage_h == s) & (bo.backup == b)].pe_without_water.max())}
                     for s in [12.0, 24.0] for b in backups},
    }
    (out / "water_reliability_summary.json").write_text(json.dumps(summary, indent=2, default=float) + "\n")
    print(json.dumps({k: summary[k] for k in ["ties", "tie_km", "cross_feeder_ties", "restored_station_share_R1",
                                              "reliability", "exposure", "sewage", "blackout"]}, indent=1, default=float))


if __name__ == "__main__":
    main()
